import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { BackupValidator } from "./validator";

// Mock dependencies
vi.mock("@/lib/db", () => ({
  db: {
    person: {
      findUnique: vi.fn(),
      findFirst: vi.fn(),
    },
    user: {
      findUnique: vi.fn(),
    },
    relationship: {
      findUnique: vi.fn(),
      findFirst: vi.fn(),
    },
  },
}));

// Mock unzipper with a simpler approach
vi.mock("unzipper", () => ({
  default: {
    Open: {
      buffer: vi.fn(),
    },
  },
}));

const { db } = await import("@/lib/db");

describe("BackupValidator", () => {
  let mockZipBuffer: Buffer;
  let validator: BackupValidator;

  const validMetadata = {
    version: "1.0.0",
    exportedAt: "2024-01-01T12:00:00.000Z",
    exportedBy: {
      id: "admin-123",
      email: "admin@example.com",
      name: "Admin User",
    },
    statistics: {
      totalPeople: 2,
      totalRelationships: 1,
      totalUsers: 1,
      totalSuggestions: 0,
      totalPhotos: 1,
      auditLogDays: 90,
      totalAuditLogs: 5,
    },
    dataFiles: [
      "data/people.json",
      "data/relationships.json",
      "data/users.json",
      "data/suggestions.json",
      "data/settings.json",
    ],
    photoDirectories: ["photos/person-1/"],
  };

  const validPeopleData = [
    {
      id: "person-1",
      firstName: "John",
      lastName: "Doe",
      email: "john@example.com",
      createdAt: "2024-01-01T12:00:00.000Z",
      updatedAt: "2024-01-01T12:00:00.000Z",
    },
    {
      id: "person-2",
      firstName: "Jane",
      lastName: "Smith",
      email: null,
      createdAt: "2024-01-02T12:00:00.000Z",
      updatedAt: "2024-01-02T12:00:00.000Z",
    },
  ];

  const validUsersData = [
    {
      id: "user-1",
      email: "admin@example.com",
      name: "Admin User",
      personId: "person-1",
      role: "ADMIN",
