    vi.doMock("fs", () => mockFs);

    // Mock archiver
    const mockArchive = {
      on: vi.fn(),
      pipe: vi.fn(),
      append: vi.fn(),
      finalize: vi.fn(),
    };
    vi.doMock("archiver", () => vi.fn(() => mockArchive));

    // Mock fs/promises for photo reading
    const mockReadFile = vi.fn().mockImplementation((path) => {
      if (path.includes("123456-photo.jpg")) {
        return Promise.resolve(Buffer.from("photo data"));
