      importPhotos: false,
      importAuditLogs: false,
    });

    expect(result).toMatchObject({
      success: true,
      importedAt: expect.any(String),
      importedBy: {
        id: "admin-123",
        email: "admin@example.com",
        name: "Admin User",
      },
      strategy: "skip",
      statistics: mockImportResult.statistics,
      errors: [],
      warnings: [],
    });
  });
});

describe("getImportHistory", () => {
