        id: "admin-123",
        email: "admin@example.com",
        name: "Admin User",
      },
      statistics: {
        totalPeople: 5,
        totalRelationships: 3,
        totalUsers: 2,
        totalSuggestions: 0,
        totalPhotos: 1,
        auditLogDays: 90,
        totalAuditLogs: 10,
      },
      dataFiles: [
        "data/people.json",
        "data/relationships.json",
        "data/users.json",
        "data/suggestions.json",
        "data/settings.json",
      ],
      photoDirectories: ["photos/person-1/"],
    },
    data: {
      people: [
        {
          id: "person-1",
          firstName: "John",
          lastName: "Doe",
          email: "john@example.com",
          maidenName: null,
          dateOfBirth: null,
          dateOfPassing: null,
          birthPlace: null,
          nativePlace: null,
          gender: null,
          photoUrl: null,
          bio: null,
          phone: null,
          currentAddress: null,
          workAddress: null,
          profession: null,
          employer: null,
          socialLinks: null,
          isLiving: true,
          createdAt: new Date("2024-01-01"),
          updatedAt: new Date("2024-01-01"),
          createdById: null,
        },
      ],
      relationships: [],
      users: [
        {
          id: "user-1",
          email: "admin@example.com",
