import { db } from "@/lib/db";
import { getStorageAdapter } from "@/lib/storage";
import { BackupValidator } from "@/lib/backup/validator";
import { ConflictResolver } from "@/lib/backup/conflict-resolver";
import { gatherBackupData, logBackupExport } from "@/actions/backup";
import {
  backupValidationSchema,
  backupImportSchema,
  type ValidationResult,
  type ImportResult,
  type ConflictResolutionStrategy,
} from "@/schemas/backup";
import archiver from "archiver";
import { writeFile, mkdir } from "fs/promises";
import { join } from "path";

export async function validateBackup(
  formData: FormData
): Promise<ValidationResult> {
  const session = await requireAdmin();

  try {
    const file = formData.get("file") as File;
    if (!file) {
      throw new Error("No file provided");
    }

    // Validate file size (max 100MB)
    const maxSize = 100 * 1024 * 1024; // 100MB
    if (file.size > maxSize) {
      throw new Error("File size exceeds 100MB limit");
    }

    // Validate file type
    if (!file.name.endsWith(".zip")) {
      throw new Error("File must be a ZIP archive");
    }

    // Convert file to buffer
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Validate backup
    const validator = new BackupValidator(buffer);
    const result = await validator.validate();

    return result;
  } catch (error) {
    console.error("Backup validation error:", error);
    throw new Error(
      `Validation failed: ${error instanceof Error ? error.message : "Unknown error"}`
    );
  }
}

export async function importBackup(
  formData: FormData,
  strategy: ConflictResolutionStrategy,
  options: {
    createBackupBeforeImport: boolean;
    importPhotos: boolean;
    importAuditLogs: boolean;
  }
): Promise<ImportResult> {
  const session = await requireAdmin();

  try {
    const file = formData.get("file") as File;
    if (!file) {
      throw new Error("No file provided");
    }

    // Convert file to buffer
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Validate backup first
    const validator = new BackupValidator(buffer);
    const validationResult = await validator.validate();

    if (!validationResult.isValid) {
      throw new Error(`Invalid backup: ${validationResult.errors.join(", ")}`);
    }

    let backupCreated: string | undefined;

    // Create backup before import if requested
    if (options.createBackupBeforeImport) {
      backupCreated = await createPreImportBackup();
    }

    // Start database transaction for atomic import
    const importResult = await db.$transaction(async (tx) => {
      // Create conflict resolver
      const resolver = new ConflictResolver(strategy, {
        id: session.id,
        email: session.email,
        name: session.name || null,
      });

      // Import data
      const { statistics, errors, warnings } = await resolver.importData(
        validator.getExtractedFiles(),
        validationResult.conflicts
      );

      // Import photos if requested
      if (options.importPhotos) {
        const photosImported = await importPhotos(
          validator.getExtractedFiles()
        );
        statistics.photosImported = photosImported;
      }

      // Log the import action
      await tx.auditLog.create({
        data: {
          userId: session.id,
          action: "CREATE",
          entityType: "BACKUP_IMPORT",
          entityId: null,
          newData: {
            timestamp: new Date().toISOString(),
            strategy,
            statistics: statistics as any,
            backupCreated,
          },
        },
      });

      return {
        success: errors.length === 0,
        importedAt: new Date().toISOString(),
        importedBy: {
          id: session.id,
          email: session.email,
          name: session.name || null,
        },
        strategy,
        statistics,
        backupCreated,
        errors,
        warnings,
      };
    });

    return importResult;
  } catch (error) {
    console.error("Backup import error:", error);

    // Log failed import attempt
    try {
      await db.auditLog.create({
        data: {
          userId: session.id,
          action: "CREATE",
          entityType: "BACKUP_IMPORT_FAILED",
          entityId: null,
          newData: {
            timestamp: new Date().toISOString(),
            error: error instanceof Error ? error.message : "Unknown error",
          },
        },
      });
    } catch (logError) {
      console.error("Failed to log import error:", logError);
    }

    throw new Error(
      `Import failed: ${error instanceof Error ? error.message : "Unknown error"}`
    );
  }
}

