    mockPersonFindMany
      .mockResolvedValueOnce(mockPeople as any)
      .mockResolvedValueOnce([]); // No photos

    const result = await gatherBackupData({
      includePhotos: false,
      includeAuditLogs: false,
      auditLogDays: 90,
    });

    expect(result.metadata.dataFiles).not.toContain("data/audit-logs.json");
    expect(result.data.auditLogs).toBeUndefined();
    expect(result.metadata.statistics.totalAuditLogs).toBe(0);
  });

  it("should exclude photos when includePhotos is false", async () => {
    // Reset mocks for this specific test
    mockPersonFindMany.mockReset();
    mockPersonFindMany.mockResolvedValueOnce(mockPeople as any);

    const result = await gatherBackupData({
      includePhotos: false,
      includeAuditLogs: true,
      auditLogDays: 90,
    });

    expect(result.photos).toEqual([]);
    expect(result.metadata.statistics.totalPhotos).toBe(0);
    expect(result.metadata.photoDirectories).toEqual([]);
  });

  it("should filter audit logs by date range", async () => {
    // Reset mocks for this specific test
    mockPersonFindMany.mockReset();
    mockPersonFindMany
      .mockResolvedValueOnce(mockPeople as any)
      .mockResolvedValueOnce([]);

    await gatherBackupData({
      includePhotos: false,
      includeAuditLogs: true,
      auditLogDays: 30,
    });

    expect(mockAuditLogFindMany).toHaveBeenCalledWith({
      where: {
        createdAt: {
          gte: expect.any(Date),
        },
      },
      orderBy: { createdAt: "desc" },
    });
  });

  it("should handle null session name", async () => {
    const sessionWithoutName = { ...mockSession, name: null };
    mockRequireAdmin.mockResolvedValue(sessionWithoutName);

    // Reset mocks for this specific test
    mockPersonFindMany.mockReset();
    mockPersonFindMany
      .mockResolvedValueOnce(mockPeople as any)
      .mockResolvedValueOnce([]);

    const result = await gatherBackupData({
      includePhotos: false,
      includeAuditLogs: false,
      auditLogDays: 90,
    });

    expect(result.metadata.exportedBy.name).toBeNull();
  });

  it("should handle empty database", async () => {
    // Reset all mocks to remove the beforeEach setup
    mockPersonFindMany.mockReset();
    mockRelationshipFindMany.mockReset();
    mockUserFindMany.mockReset();
    mockSuggestionFindMany.mockReset();
    mockFamilySettingsFindFirst.mockReset();
    mockAuditLogFindMany.mockReset();

    // Re-setup admin auth
    mockRequireAdmin.mockResolvedValue(mockSession);

    // Setup empty database mocks
    mockPersonFindMany.mockResolvedValue([]);
    mockRelationshipFindMany.mockResolvedValue([]);
    mockUserFindMany.mockResolvedValue([]);
    mockSuggestionFindMany.mockResolvedValue([]);
    mockFamilySettingsFindFirst.mockResolvedValue(null);
    mockAuditLogFindMany.mockResolvedValue([]);

    const result = await gatherBackupData({
      includePhotos: false,
      includeAuditLogs: false,
      auditLogDays: 90,
    });

    expect(result.metadata.statistics).toEqual({
      totalPeople: 0,
      totalRelationships: 0,
      totalUsers: 0,
      totalSuggestions: 0,
      totalPhotos: 0,
      auditLogDays: 90,
      totalAuditLogs: 0,
    });

    expect(result.data.settings).toBeNull();
  });

  it("should validate input parameters", async () => {
    await expect(
      gatherBackupData({
        includePhotos: true,
        includeAuditLogs: true,
        auditLogDays: 0, // Invalid: below minimum
      })
    ).rejects.toThrow();

    await expect(
      gatherBackupData({
        includePhotos: true,
        includeAuditLogs: true,
        auditLogDays: 366, // Invalid: above maximum
      })
    ).rejects.toThrow();
  });
});

