                      <p className="text-sm text-muted-foreground">Age {age}</p>
                    )}
                  </div>
                </div>
              )}
              {person.dateOfPassing && (
                <div className="flex items-center gap-3">
                  <Calendar className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="text-sm text-muted-foreground">Passed</p>
                    <p>{formatDate(person.dateOfPassing)}</p>
                    {age !== null && (
                      <p className="text-sm text-muted-foreground">Age {age}</p>
                    )}
                  </div>
                </div>
              )}
              {(person.birthPlace || person.nativePlace) && (
                <div className="flex items-center gap-3">
                  <MapPin className="h-4 w-4 text-muted-foreground" />
                  <div>
                    {person.birthPlace && (
                      <>
                        <p className="text-sm text-muted-foreground">
                          Birth Place
                        </p>
                        <p>{person.birthPlace}</p>
                      </>
                    )}
                    {person.nativePlace && (
                      <>
                        <p className="text-sm text-muted-foreground">
                          Native Place
                        </p>
                        <p>{person.nativePlace}</p>
                      </>
                    )}
                  </div>
                </div>
              )}
              {person.profession && (
                <div className="flex items-center gap-3">
                  <Briefcase className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="text-sm text-muted-foreground">Profession</p>
                    <p>{person.profession}</p>
                    {person.employer && (
                      <p className="text-sm text-muted-foreground">
                        at {person.employer}
                      </p>
                    )}
                  </div>
                </div>
              )}
              {person.email && (
                <div className="flex items-center gap-3">
                  <Mail className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={`mailto:${person.email}`}
                    className="text-primary hover:underline"
                  >
                    {person.email}
                  </a>
                </div>
              )}
              {person.phone && (
                <div className="flex items-center gap-3">
                  <Phone className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={`tel:${person.phone}`}
                    className="text-primary hover:underline"
                  >
                    {person.phone}
                  </a>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        <div className="space-y-6 lg:col-span-2">
          {person.bio && (
            <Card>
              <CardHeader>
                <CardTitle>About</CardTitle>
              </CardHeader>
              <CardContent>
                <p className="whitespace-pre-wrap">{person.bio}</p>
              </CardContent>
            </Card>
          )}

          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle className="flex items-center gap-2">
                  <Users className="h-5 w-5" />
                  Relationships
                </CardTitle>
                <CardDescription>
                  Family connections and relationships
                </CardDescription>
              </div>
              {canEdit && <AddRelationshipButton personId={person.id} />}
            </CardHeader>
            <CardContent>
              <Tabs defaultValue="parents">
                <TabsList className="grid w-full grid-cols-4">
                  <TabsTrigger value="parents">
                    Parents ({parents.length})
                  </TabsTrigger>
                  <TabsTrigger value="spouse">
                    Spouse ({spouses.length})
                  </TabsTrigger>
                  <TabsTrigger value="children">
                    Children ({children.length})
                  </TabsTrigger>
                  <TabsTrigger value="siblings">
                    Siblings ({siblings.length})
                  </TabsTrigger>
                </TabsList>
                <TabsContent value="parents">
                  <RelationshipsList
                    relationships={parents}
                    emptyMessage="No parents added"
                    canEdit={canEdit}
                  />
                </TabsContent>
                <TabsContent value="spouse">
                  <RelationshipsList
                    relationships={spouses}
                    emptyMessage="No spouse added"
                    showMarriageInfo
                    canEdit={canEdit}
                  />
                </TabsContent>
                <TabsContent value="children">
                  <RelationshipsList
                    relationships={children}
                    emptyMessage="No children added"
                    canEdit={canEdit}
                  />
                </TabsContent>
                <TabsContent value="siblings">
                  <RelationshipsList
                    relationships={siblings}
                    emptyMessage="No siblings added"
                    canEdit={canEdit}
                  />
                </TabsContent>
              </Tabs>
            </CardContent>
          </Card>
        </div>
      </div>

      <Dialog open={editOpen} onOpenChange={setEditOpen}>
        <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>Edit Profile</DialogTitle>
          </DialogHeader>
          <PersonForm person={person} onSuccess={() => setEditOpen(false)} />
        </DialogContent>
      </Dialog>
    </div>
  );
}

function getInverseType(type: string): string {
  switch (type) {
    case "PARENT":
      return "CHILD";
    case "CHILD":
      return "PARENT";
    default:
      return type;
  }
}

