        totalConflicts: conflicts.length,
        conflictsByType,
        conflictsBySeverity,
      },
      errors,
      warnings,
    };
  }

  getExtractedFiles(): Map<string, any> {
    return this.extractedFiles;
  }

  getMetadata(): BackupMetadata | null {
    return this.metadata;
  }
