import unzipper from "unzipper";
import { z } from "zod";
import { db } from "@/lib/db";
import {
  backupMetadataSchema,
  type BackupMetadata,
  type Conflict,
  type ValidationResult,
} from "@/schemas/backup";
import type { DataItem } from "@/lib/backup/types";

// Supported backup versions
const SUPPORTED_VERSIONS = ["1.0.0"];
const _CURRENT_VERSION = "1.0.0";

// Data schemas for validation
const personDataSchema = z.object({
  id: z.string(),
  firstName: z.string(),
  lastName: z.string(),
  email: z.string().nullable().optional(),
  createdAt: z.string(),
  updatedAt: z.string(),
});

const userDataSchema = z.object({
  id: z.string(),
  email: z.string(),
  name: z.string().nullable().optional(),
  personId: z.string().nullable().optional(),
  role: z.enum(["ADMIN", "MEMBER", "VIEWER"]),
  createdAt: z.string(),
  updatedAt: z.string(),
});

const relationshipDataSchema = z.object({
  id: z.string(),
  personId: z.string(),
  relatedPersonId: z.string(),
  type: z.enum(["PARENT", "CHILD", "SPOUSE", "SIBLING"]),
  createdAt: z.string(),
  updatedAt: z.string(),
});

