  private async detectPeopleConflicts(peopleData: DataItem[]): Promise<Conflict[]> {
    const conflicts: Conflict[] = [];

    for (const person of peopleData) {
      // Check for ID conflicts
      const existingById = await db.person.findUnique({
        where: { id: person.id },
      });

      if (existingById) {
        conflicts.push({
          type: "person",
          action: "update",
          existingId: existingById.id,
          existingData: existingById,
          newData: person,
          conflictFields: this.getChangedFields(existingById, person),
          severity: "medium",
          description: `Person with ID ${person.id} already exists`,
        });
        continue;
      }

      // Check for email conflicts
      if (person.email) {
        const existingByEmail = await db.person.findFirst({
          where: { email: person.email },
        });

        if (existingByEmail) {
          conflicts.push({
            type: "person",
            action: "create",
            existingId: existingByEmail.id,
            existingData: existingByEmail,
            newData: person,
            conflictFields: ["email"],
            severity: "high",
            description: `Person with email ${person.email} already exists`,
          });
        }
      }

      // Check for name conflicts (potential duplicates)
      const existingByName = await db.person.findFirst({
        where: {
          firstName: person.firstName,
          lastName: person.lastName,
          dateOfBirth: person.dateOfBirth
            ? new Date(person.dateOfBirth)
            : undefined,
        },
      });

      if (existingByName) {
        conflicts.push({
          type: "person",
          action: "create",
          existingId: existingByName.id,
          existingData: existingByName,
          newData: person,
          conflictFields: ["firstName", "lastName", "dateOfBirth"],
          severity: "low",
          description: `Potential duplicate person: ${person.firstName} ${person.lastName}`,
        });
      }
    }

    return conflicts;
  }

  private async detectUserConflicts(usersData: DataItem[]): Promise<Conflict[]> {
    const conflicts: Conflict[] = [];

    for (const user of usersData) {
      // Check for ID conflicts
      const existingById = await db.user.findUnique({
        where: { id: user.id },
      });

      if (existingById) {
        conflicts.push({
          type: "user",
          action: "update",
          existingId: existingById.id,
          existingData: existingById,
          newData: user,
          conflictFields: this.getChangedFields(existingById, user),
          severity: "high",
          description: `User with ID ${user.id} already exists`,
        });
        continue;
      }

      // Check for email conflicts
      const existingByEmail = await db.user.findUnique({
        where: { email: user.email },
      });

      if (existingByEmail) {
        conflicts.push({
          type: "user",
          action: "create",
          existingId: existingByEmail.id,
          existingData: existingByEmail,
          newData: user,
          conflictFields: ["email"],
          severity: "high",
          description: `User with email ${user.email} already exists`,
        });
      }
    }

    return conflicts;
  }

  private async detectRelationshipConflicts(
    relationshipsData: unknown[]
  ): Promise<Conflict[]> {
    const conflicts: Conflict[] = [];

    for (const relationship of relationshipsData) {
      // Check for ID conflicts
      const existingById = await db.relationship.findUnique({
        where: { id: relationship.id },
      });

      if (existingById) {
        conflicts.push({
          type: "relationship",
          action: "update",
          existingId: existingById.id,
          existingData: existingById,
          newData: relationship,
          conflictFields: this.getChangedFields(existingById, relationship),
          severity: "medium",
          description: `Relationship with ID ${relationship.id} already exists`,
        });
        continue;
      }

      // Check for duplicate relationships
      const existingRelationship = await db.relationship.findFirst({
        where: {
          personId: relationship.personId,
          relatedPersonId: relationship.relatedPersonId,
          type: relationship.type,
        },
      });

      if (existingRelationship) {
        conflicts.push({
          type: "relationship",
          action: "create",
          existingId: existingRelationship.id,
          existingData: existingRelationship,
          newData: relationship,
          conflictFields: ["personId", "relatedPersonId", "type"],
          severity: "medium",
          description: `Duplicate relationship between ${relationship.personId} and ${relationship.relatedPersonId}`,
        });
      }
    }

    return conflicts;
  }

  private getChangedFields(existing: unknown, incoming: unknown): string[] {
    const changedFields: string[] = [];

    for (const key in incoming) {
      if (existing[key] !== incoming[key]) {
        changedFields.push(key);
      }
    }

    return changedFields;
  }

  private createValidationResult(
    isValid: boolean,
    conflicts: Conflict[],
    errors: string[],
    warnings: string[]
  ): ValidationResult {
    const conflictsByType: Record<string, number> = {};
    const conflictsBySeverity: Record<string, number> = {};

    for (const conflict of conflicts) {
      conflictsByType[conflict.type] =
        (conflictsByType[conflict.type] || 0) + 1;
      conflictsBySeverity[conflict.severity] =
        (conflictsBySeverity[conflict.severity] || 0) + 1;
    }

    return {
      isValid,
      metadata: this.metadata!,
      conflicts,
      statistics: {
        totalConflicts: conflicts.length,
        conflictsByType,
        conflictsBySeverity,
      },
      errors,
      warnings,
    };
  }

  getExtractedFiles(): Map<string, any> {
    return this.extractedFiles;
  }

  getMetadata(): BackupMetadata | null {
    return this.metadata;
  }
}

