    } catch (error) {
      errors.push(
        `Invalid metadata format: ${error instanceof Error ? error.message : "Unknown error"}`
      );
      return { isValid: false, errors };
    }
  }

  private async validateDataFiles(): Promise<{
    isValid: boolean;
