          where: { email: person.email },
        });

        if (existingByEmail) {
          conflicts.push({
            type: "person",
            action: "create",
            existingId: existingByEmail.id,
            existingData: existingByEmail,
            newData: person,
            conflictFields: ["email"],
            severity: "high",
            description: `Person with email ${person.email} already exists`,
          });
        }
      }

