        archive.append(JSON.stringify(data.auditLogs, null, 2), {
          name: "data/audit-logs.json",
        });
      }

      // Add photos
      if (photos.length > 0) {
        addPhotosToBackupArchive(archive, photos);
      } else {
        archive.finalize();
      }
    });
