import { describe, it, expect, beforeEach, mock } from "bun:test";
import bcrypt from "bcryptjs";

// Mock bcrypt
const mockBcryptCompare = mock(async () => true);
mock.module("bcryptjs", () => ({
  compare: mockBcryptCompare,
}));

// Mock database
const mockDbUserFindUnique = mock(async () => null);
const mockDbUserUpdate = mock(async (args: any) => ({ id: args.where.id }));

mock.module("./db", () => ({
  db: {
    user: {
      findUnique: mockDbUserFindUnique,
      update: mockDbUserUpdate,
    },
  },
}));

// Import after mocking
const { authOptions } = await import("./auth-options");

const createMockUser = (overrides = {}) => ({
  id: "user-123",
  email: "user@example.com",
  name: "Test User",
  role: "ADMIN",
  personId: "person-123",
  passwordHash: "$2a$10$hashedpassword",
  isActive: true,
  mustChangePassword: false,
  ...overrides,
});

describe("authOptions", () => {
  beforeEach(() => {
    mockDbUserFindUnique.mockClear();
    mockDbUserUpdate.mockClear();
    mockBcryptCompare.mockClear();
  });

  it("exports authOptions object", () => {
    expect(authOptions).toBeDefined();
    expect(authOptions.providers).toBeDefined();
    expect(authOptions.session).toBeDefined();
    expect(authOptions.pages).toBeDefined();
    expect(authOptions.callbacks).toBeDefined();
  });

  it("has PrismaAdapter", () => {
    expect(authOptions.adapter).toBeDefined();
  });

  it("uses JWT session strategy", () => {
    expect(authOptions.session?.strategy).toBe("jwt");
  });

  it("sets session maxAge to 30 days", () => {
    const thirtyDaysInSeconds = 30 * 24 * 60 * 60;
    expect(authOptions.session?.maxAge).toBe(thirtyDaysInSeconds);
  });

  it("redirects to /login on sign in", () => {
    expect(authOptions.pages?.signIn).toBe("/login");
  });

  it("redirects to /login on error", () => {
    expect(authOptions.pages?.error).toBe("/login");
  });

  describe("CredentialsProvider", () => {
    let credentialsProvider: any;

    beforeEach(() => {
      credentialsProvider = authOptions.providers?.[0];
    });

    it("has credentials provider", () => {
      expect(credentialsProvider).toBeDefined();
      expect(credentialsProvider.name).toBe("Email");
    });

    it("requires email credential", () => {
      expect(credentialsProvider.credentials?.email).toBeDefined();
      expect(credentialsProvider.credentials.email.label).toBe("Email");
      expect(credentialsProvider.credentials.email.type).toBe("email");
    });

    it("requires password credential", () => {
      expect(credentialsProvider.credentials?.password).toBeDefined();
      expect(credentialsProvider.credentials.password.label).toBe("Password");
      expect(credentialsProvider.credentials.password.type).toBe("password");
    });

    describe("authorize callback", () => {
      let authorize: any;

      beforeEach(() => {
        authorize = credentialsProvider.authorize;
      });

      it("throws error when email is missing", async () => {
        try {
          await authorize({ password: "password123" });
          expect.fail("Should have thrown");
        } catch (error) {
          expect((error as Error).message).toBe(
            "Email and password are required"
          );
        }
      });

      it("throws error when password is missing", async () => {
        try {
          await authorize({ email: "user@example.com" });
          expect.fail("Should have thrown");
        } catch (error) {
          expect((error as Error).message).toBe(
            "Email and password are required"
          );
        }
      });

      it("throws error when both email and password are missing", async () => {
        try {
          await authorize({});
          expect.fail("Should have thrown");
        } catch (error) {
          expect((error as Error).message).toBe(
            "Email and password are required"
          );
        }
      });

      it("lowercases email for lookup", async () => {
        mockDbUserFindUnique.mockResolvedValueOnce(null);
        try {
          await authorize({
            email: "User@EXAMPLE.COM",
            password: "password",
          });
        } catch {
          // Expected to fail, just checking email lowercasing
        }
        const callArgs = mockDbUserFindUnique.mock.calls[0];
        expect(callArgs[0].where.email).toBe("user@example.com");
      });

      it("throws error when user not found", async () => {
        mockDbUserFindUnique.mockResolvedValueOnce(null);
        try {
          await authorize({
            email: "nonexistent@example.com",
            password: "password",
          });
          expect.fail("Should have thrown");
        } catch (error) {
          expect((error as Error).message).toBe(
            "Invalid email or password"
          );
        }
      });

      it("throws error when user has no password hash", async () => {
        const user = createMockUser({ passwordHash: null });
        mockDbUserFindUnique.mockResolvedValueOnce(user);
        try {
          await authorize({
            email: "user@example.com",
            password: "password",
          });
          expect.fail("Should have thrown");
        } catch (error) {
          expect((error as Error).message).toBe(
            "Invalid email or password"
          );
        }
      });

      it("throws error when user account is disabled", async () => {
        const user = createMockUser({ isActive: false });
        mockDbUserFindUnique.mockResolvedValueOnce(user);
        try {
          await authorize({
            email: "user@example.com",
            password: "password",
          });
          expect.fail("Should have thrown");
