      expect(result.user.name).toBe("Test User");
    });

    it("returns session when token is valid", async () => {
      const token = {
        id: "user-123",
        role: "VIEWER",
        personId: "person-123",
        mustChangePassword: false,
      };
      const session = {
        user: {
          email: "user@example.com",
        },
      };
      const result = await sessionCallback({ session, token });
      expect(result).toEqual(session);
    });

    it("handles missing token gracefully", async () => {
      const session = {
        user: {
          email: "user@example.com",
          name: "Test User",
        },
      };
      const result = await sessionCallback({ session, token: null });
      expect(result).toEqual(session);
    });

    it("handles missing session.user gracefully", async () => {
      const token = {
        id: "user-123",
        role: "ADMIN",
        personId: "person-123",
        mustChangePassword: false,
      };
      const session = {};
      const result = await sessionCallback({ session, token });
      expect(result).toEqual(session);
    });
  });
});

