        statistics: {
          totalPeople: 5,
          totalRelationships: 3,
          totalUsers: 2,
          totalSuggestions: 0,
          totalPhotos: 1,
          auditLogDays: 90,
          totalAuditLogs: 10,
        },
        dataFiles: ["data/people.json"],
