      expect(credentialsProvider).toBeDefined();
      expect(credentialsProvider?.name).toBe("Credentials");
    });

    it("has authorize function on credentials provider", () => {
      const credentialsProvider = authOptions.providers?.[0];
      expect(typeof credentialsProvider?.authorize).toBe("function");
    });

    it("has session configuration with JWT strategy", () => {
      expect(authOptions.session).toBeDefined();
      expect(authOptions.session?.strategy).toBe("jwt");
    });

    it("sets session maxAge to 30 days in seconds", () => {
      const thirtyDaysInSeconds = 30 * 24 * 60 * 60;
      expect(authOptions.session?.maxAge).toBe(thirtyDaysInSeconds);
    });

    it("has pages configuration", () => {
      expect(authOptions.pages).toBeDefined();
      expect(authOptions.pages?.signIn).toBe("/login");
      expect(authOptions.pages?.error).toBe("/login");
    });

    it("has callbacks configured", () => {
      expect(authOptions.callbacks).toBeDefined();
      expect(typeof authOptions.callbacks?.jwt).toBe("function");
      expect(typeof authOptions.callbacks?.session).toBe("function");
    });
  });

  describe("authorize function", () => {
    it("authorizes user with valid credentials", async () => {
      mockBcryptCompare.mockResolvedValue(true);
      mockDbUser.findUnique.mockResolvedValue({
        id: "user-1",
        email: "admin@example.com",
        name: "Admin User",
        passwordHash: "$2a$10$hashedpassword",
        isActive: true,
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      });

      const credentialsProvider = authOptions.providers?.[0];
      const result = await credentialsProvider?.authorize?.({
        email: "admin@example.com",
        password: "password123",
      });

      expect(result).toBeDefined();
      expect(result?.id).toBe("user-1");
      expect(result?.email).toBe("admin@example.com");
      expect(result?.role).toBe("ADMIN");
    });

    it("throws error when email is missing", async () => {
      const credentialsProvider = authOptions.providers?.[0];
      try {
        await credentialsProvider?.authorize?.({
          password: "password123",
        });
        expect.fail("Should have thrown error");
      } catch (error) {
        expect((error as Error).message).toBe("Email and password are required");
      }
    });

    it("throws error when password is missing", async () => {
      const credentialsProvider = authOptions.providers?.[0];
      try {
        await credentialsProvider?.authorize?.({
          email: "admin@example.com",
        });
        expect.fail("Should have thrown error");
      } catch (error) {
        expect((error as Error).message).toBe("Email and password are required");
      }
    });

    it("throws error when user not found", async () => {
      mockDbUser.findUnique.mockResolvedValue(null);

      const credentialsProvider = authOptions.providers?.[0];
      try {
        await credentialsProvider?.authorize?.({
          email: "nonexistent@example.com",
          password: "password123",
        });
        expect.fail("Should have thrown error");
      } catch (error) {
        expect((error as Error).message).toBe("Invalid email or password");
      }
    });

    it("throws error when user has no password hash", async () => {
      mockDbUser.findUnique.mockResolvedValue({
        id: "user-1",
        email: "admin@example.com",
        name: "Admin User",
        passwordHash: null,
        isActive: true,
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      });

      const credentialsProvider = authOptions.providers?.[0];
      try {
        await credentialsProvider?.authorize?.({
          email: "admin@example.com",
          password: "password123",
        });
        expect.fail("Should have thrown error");
      } catch (error) {
        expect((error as Error).message).toBe("Invalid email or password");
      }
    });

    it("throws error when account is inactive", async () => {
      mockDbUser.findUnique.mockResolvedValue({
        id: "user-1",
        email: "admin@example.com",
        name: "Admin User",
        passwordHash: "$2a$10$hashedpassword",
        isActive: false,
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      });

      const credentialsProvider = authOptions.providers?.[0];
      try {
        await credentialsProvider?.authorize?.({
          email: "admin@example.com",
          password: "password123",
        });
        expect.fail("Should have thrown error");
      } catch (error) {
        expect((error as Error).message).toBe("Account is disabled");
      }
    });

    it("throws error when password is invalid", async () => {
      mockBcryptCompare.mockResolvedValue(false);
      mockDbUser.findUnique.mockResolvedValue({
        id: "user-1",
        email: "admin@example.com",
        name: "Admin User",
        passwordHash: "$2a$10$hashedpassword",
        isActive: true,
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      });

      const credentialsProvider = authOptions.providers?.[0];
      try {
        await credentialsProvider?.authorize?.({
          email: "admin@example.com",
          password: "wrongpassword",
        });
        expect.fail("Should have thrown error");
      } catch (error) {
        expect((error as Error).message).toBe("Invalid email or password");
      }
    });

    it("updates lastLoginAt on successful authorization", async () => {
      mockBcryptCompare.mockResolvedValue(true);
      mockDbUser.findUnique.mockResolvedValue({
        id: "user-1",
        email: "admin@example.com",
        name: "Admin User",
        passwordHash: "$2a$10$hashedpassword",
        isActive: true,
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      });

      const credentialsProvider = authOptions.providers?.[0];
      await credentialsProvider?.authorize?.({
        email: "admin@example.com",
        password: "password123",
      });

      expect(mockDbUser.update).toHaveBeenCalled();
      const updateCall = mockDbUser.update.mock.calls[0];
      expect(updateCall[0]).toEqual({
        where: { id: "user-1" },
        data: { lastLoginAt: expect.any(Date) },
      });
    });

    it("lowercases email before lookup", async () => {
      mockBcryptCompare.mockResolvedValue(true);
      mockDbUser.findUnique.mockResolvedValue({
        id: "user-1",
        email: "admin@example.com",
        name: "Admin User",
        passwordHash: "$2a$10$hashedpassword",
        isActive: true,
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      });

      const credentialsProvider = authOptions.providers?.[0];
      await credentialsProvider?.authorize?.({
        email: "ADMIN@EXAMPLE.COM",
        password: "password123",
      });

      const findUniqueCall = mockDbUser.findUnique.mock.calls[0];
      expect(findUniqueCall[0]).toEqual({
        where: { email: "admin@example.com" },
      });
    });

    it("returns user object with all required fields", async () => {
      mockBcryptCompare.mockResolvedValue(true);
      mockDbUser.findUnique.mockResolvedValue({
        id: "user-123",
        email: "test@example.com",
        name: "Test User",
        passwordHash: "$2a$10$hashedpassword",
        isActive: true,
        role: "MEMBER",
        personId: "person-456",
        mustChangePassword: true,
      });

      const credentialsProvider = authOptions.providers?.[0];
      const result = await credentialsProvider?.authorize?.({
        email: "test@example.com",
        password: "password123",
      });

      expect(result).toEqual({
        id: "user-123",
        email: "test@example.com",
        name: "Test User",
        role: "MEMBER",
        personId: "person-456",
        mustChangePassword: true,
      });
    });
  });

  describe("jwt callback", () => {
    let jwtCallback: any;

    beforeEach(() => {
      jwtCallback = authOptions.callbacks?.jwt;
    });

    it("jwt callback exists", () => {
      expect(typeof jwtCallback).toBe("function");
    });

    it("jwt callback adds user properties to token on sign in", async () => {
      const token: any = {};
      const user = {
        id: "user-1",
        email: "user@example.com",
        name: "Test User",
        role: "ADMIN" as const,
        personId: "person-1",
        mustChangePassword: false,
      };
      const result = await jwtCallback({ token, user });
      expect(result.id).toBe("user-1");
      expect(result.role).toBe("ADMIN");
      expect(result.personId).toBe("person-1");
      expect(result.mustChangePassword).toBe(false);
    });

    it("jwt callback preserves token when no user", async () => {
      const token = { id: "user-1", role: "ADMIN" } as any;
      const result = await jwtCallback({ token, user: null });
      expect(result.id).toBe("user-1");
      expect(result.role).toBe("ADMIN");
    });

    it("jwt callback updates token on session update", async () => {
      const token: any = {
        id: "user-1",
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      };
      const session = { role: "MEMBER", mustChangePassword: true };
      const result = await jwtCallback({
        token,
        user: null,
        trigger: "update",
        session,
      });
      expect(result.role).toBe("MEMBER");
      expect(result.mustChangePassword).toBe(true);
    });

    it("jwt callback falls back to existing token values on partial update", async () => {
      const token: any = {
        id: "user-1",
        role: "ADMIN",
        personId: "person-1",
        mustChangePassword: false,
      };
      const session = { role: "MEMBER" };
      const result = await jwtCallback({
        token,
        user: null,
        trigger: "update",
        session,
      });
      expect(result.role).toBe("MEMBER");
      expect(result.personId).toBe("person-1");
      expect(result.mustChangePassword).toBe(false);
    });

    it("jwt callback does not update token without trigger update", async () => {
      const token: any = { id: "user-1", role: "ADMIN" };
      const session = { role: "MEMBER" };
      const result = await jwtCallback({
        token,
        user: null,
        trigger: "signIn",
        session,
      });
      expect(result.role).toBe("ADMIN");
    });
  });

  describe("session callback", () => {
    let sessionCallback: any;

    beforeEach(() => {
      sessionCallback = authOptions.callbacks?.session;
    });

    it("session callback exists", () => {
      expect(typeof sessionCallback).toBe("function");
    });

    it("session callback enriches session with token data", async () => {
      const session: any = {
        user: { email: "test@example.com" },
      };
      const token: any = {
        id: "user-1",
        role: "ADMIN",
        personId: "person-1",
        mustChangePassword: false,
      };
      const result = await sessionCallback({ session, token });
      expect(result.user.id).toBe("user-1");
      expect(result.user.role).toBe("ADMIN");
      expect(result.user.personId).toBe("person-1");
      expect(result.user.mustChangePassword).toBe(false);
    });

    it("session callback handles empty token gracefully", async () => {
      const session: any = { user: { email: "test@example.com" } };
      const result = await sessionCallback({ session, token: null });
      expect(result.user).toBeDefined();
      expect(result.user.email).toBe("test@example.com");
    });

    it("session callback preserves existing session properties", async () => {
      const originalSession: any = {
        user: {
          email: "user@example.com",
          name: "Test User",
        },
      };
      const token: any = {
        id: "1",
        role: "ADMIN",
        personId: null,
        mustChangePassword: false,
      };
      const result = await sessionCallback({
        session: originalSession,
        token,
      });
      expect(result.user.email).toBe("user@example.com");
      expect(result.user.name).toBe("Test User");
      expect(result.user.id).toBe("1");
      expect(result.user.role).toBe("ADMIN");
    });

    it("session callback returns modified session object", async () => {
      const session: any = {
        user: {
          email: "test@example.com",
          id: "existing-id",
        },
      };
      const token: any = {
        id: "token-id",
        role: "VIEWER",
        personId: "person-2",
        mustChangePassword: true,
      };
      const result = await sessionCallback({ session, token });
      expect(result.user.id).toBe("token-id");
      expect(result.user.role).toBe("VIEWER");
      expect(result.user.personId).toBe("person-2");
      expect(result.user.mustChangePassword).toBe(true);
    });

    it("session callback handles all token properties", async () => {
      const session: any = { user: { email: "user@test.com" } };
      const token: any = {
        id: "full-user-id",
        role: "ADMIN" as const,
        personId: "person-abc",
        mustChangePassword: true,
      };
      const result = await sessionCallback({ session, token });
      expect(result.user.id).toBe("full-user-id");
      expect(result.user.role).toBe("ADMIN");
      expect(result.user.personId).toBe("person-abc");
      expect(result.user.mustChangePassword).toBe(true);
    });
  });
});

