        const user = {
          id: `user-${role}`,
          email: `user-${role}@example.com`,
          name: `Test ${role}`,
          role,
          personId: null,
          mustChangePassword: false,
        };
        const result = await jwtCallback({ token, user });
        expect(result.role).toBe(role);
      }
    });
  });

