    });
    formData.append("file", validFile);

    const result = await importBackupCore(
      formData,
      "skip",
      { ...defaultOptions, createBackupBeforeImport: true },
      deps
    );

    expect(result.success).toBe(true);
    expect(capturedOptions).toEqual({
      includePhotos: true,
      includeAuditLogs: true,
