describe("importBackupCore - pre-import backup and photo import", () => {
  const defaultOptions = {
    createBackupBeforeImport: false,
    importPhotos: false,
    importAuditLogs: false,
  };

  it("should handle error creating pre-import backup gracefully", async () => {
