      name: "Admin User",
    });
  });

  it("should include conflict validation result in import", async () => {
    const deps = createMockDependencies({
      createValidator: () => ({
        validate: async (): Promise<ValidationResult> => ({
          isValid: true,
          metadata: {} as any,
          conflicts: [
            {
              personId: "person-1",
              field: "name",
              currentValue: "John Doe",
              importedValue: "John D.",
              resolution: "skip" as const,
