    let updateCount = 0;

    const deps = createMockDependencies({
      getStorageAdapter: () => ({
        upload: async () => {
          uploadCount++;
          return `${uploadCount}-photo.jpg`;
        },
        getUrl: (path: string) => `http://localhost:3000/api/uploads/${path}`,
        delete: async () => {},
