      db: {
        person: {
          findUnique: async ({ where }: any) => ({
            id: where.id,
            name: "Person",
          }),
          update: async () => {
            updateCount++;
            return {};
          },
        },
      } as any,
    });

    const extractedFiles = new Map([
      ["photos/person-1/photo1.jpg", Buffer.from("image 1")],
      ["photos/person-2/photo2.jpg", Buffer.from("image 2")],
      ["photos/person-3/photo3.jpg", Buffer.from("image 3")],
